-- MySQL 8 / PHP 8.3 foundation. Amounts use DECIMAL; tenant branch scope is explicit.
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE branches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, address VARCHAR(255), latitude DECIMAL(10,7), longitude DECIMAL(10,7), attendance_radius_m INT UNSIGNED DEFAULT 150, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id BIGINT UNSIGNED NULL, full_name VARCHAR(150) NOT NULL, email VARCHAR(190) UNIQUE, phone VARCHAR(30), password_hash VARCHAR(255) NOT NULL, status ENUM('active','inactive') DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(branch_id) REFERENCES branches(id));
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id BIGINT UNSIGNED NOT NULL, code VARCHAR(30) NOT NULL UNIQUE, full_name VARCHAR(150) NOT NULL, phone VARCHAR(30) NOT NULL, status VARCHAR(30) DEFAULT 'lead', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(branch_id,phone), FOREIGN KEY(branch_id) REFERENCES branches(id));
CREATE TABLE courses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id BIGINT UNSIGNED NOT NULL, name VARCHAR(200) NOT NULL, tuition DECIMAL(15,2) NOT NULL DEFAULT 0, FOREIGN KEY(branch_id) REFERENCES branches(id));
CREATE TABLE classes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id BIGINT UNSIGNED NOT NULL, course_id BIGINT UNSIGNED NOT NULL, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, teacher_id BIGINT UNSIGNED NULL, starts_on DATE, ends_on DATE, status ENUM('draft','upcoming','active','completed','cancelled') DEFAULT 'draft', INDEX(branch_id,status), FOREIGN KEY(branch_id) REFERENCES branches(id), FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(teacher_id) REFERENCES users(id));
CREATE TABLE students (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL UNIQUE, code VARCHAR(30) NOT NULL UNIQUE, full_name VARCHAR(150) NOT NULL, phone VARCHAR(30), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE enrollments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, class_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, status ENUM('active','paused','completed','dropped') DEFAULT 'active', UNIQUE KEY unique_enrollment(class_id,student_id), FOREIGN KEY(class_id) REFERENCES classes(id), FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE class_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, class_id BIGINT UNSIGNED NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, room VARCHAR(100), is_open BOOLEAN DEFAULT FALSE, FOREIGN KEY(class_id) REFERENCES classes(id), INDEX(class_id,starts_at));
CREATE TABLE attendance_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, session_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, status ENUM('present','late','absent','excused','pending_verification') NOT NULL, checked_in_at DATETIME NULL, photo_path VARCHAR(255) NULL, latitude DECIMAL(10,7) NULL, longitude DECIMAL(10,7) NULL, accuracy_m DECIMAL(9,2) NULL, verification_reason TEXT NULL, updated_by BIGINT UNSIGNED NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY one_official_attendance(session_id,student_id), FOREIGN KEY(session_id) REFERENCES class_sessions(id), FOREIGN KEY(student_id) REFERENCES students(id), FOREIGN KEY(updated_by) REFERENCES users(id));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, branch_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, before_json JSON NULL, after_json JSON NULL, ip_address VARCHAR(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(entity_type,entity_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(branch_id) REFERENCES branches(id));
